import {TYPE_NAMES,icon} from './art.mjs';
import {addXP} from './training.mjs';
export const DEN_BOSSES=[94,6,249,150,384,487];
export function denBoss(dex,floor){const pool=DEN_BOSSES.filter(id=>dex[id]);return dex[pool[(floor-1)%pool.length]]}
export function canEnterDen(s,floor){return Number.isSafeInteger(floor)&&floor>=1&&floor<=s.denFloor}
export function awardDenVictory(s,floor,keys=s.team){if(!canEnterDen(s,floor)||floor<s.denFloor)return null;const r={tickets:2,candies:2,coins:50,xp:30+floor*10};s.denFloor=floor+1;s.candies+=r.candies;s.tickets+=r.tickets;s.coins+=r.coins;for(const key of new Set(keys))if(s.roster.includes(key))addXP(s,key,r.xp);return r}
export function denPage(g){const frontier=g.state.denFloor,floor=canEnterDen(g.state,g.denSelected)?g.denSelected:frontier,boss=denBoss(g.dex,floor),old=floor<frontier;g.denSelected=floor;const limit=g.denHistoryLimit||12,start=Math.max(1,frontier-limit);
 return g.heading('LES GARDIENS DES PROFONDEURS','L’Antre','Au-delà de la roche, un gardien t’attend. Entre seul ou rassemble jusqu’à quatre dresseurs.')+`<div class="den-layout"><section class="den-expedition"><div class="den-cave"><div class="den-cave-sky"></div><div class="den-cave-mountain"></div><div class="den-dynamax-clouds"></div><div class="den-dynamax-beam"></div><div class="den-cave-mouth">${old?`<img src="${icon(String(boss.id))}" alt="${boss.name}">`:''}</div><div class="den-cave-floor"></div><div class="den-torch torch-left">♨</div><div class="den-torch torch-right">♨</div><span class="den-cave-label">ANTRE ${String(floor).padStart(2,'0')} · ${old?'DÉJÀ VAINCU':'PROCHAIN GARDIEN'}</span><div class="den-type-stones" aria-label="Types du gardien">${boss.types.map(t=>`<span data-den-type="${t}" style="--stone:${({ghost:'#9f89cd',poison:'#bd7fcc',fire:'#f39565',flying:'#9ebcde',psychic:'#e592be',dragon:'#a6a0ed',water:'#80c4e8'})[t]||'#b5cbab'}">${TYPE_NAMES[t]}</span>`).join('')}</div></div><div class="den-gate-copy"><span class="eyebrow">${old?'LE GARDIEN A DÉJÀ ÉTÉ VAINCU':'UNE PRÉSENCE DERRIÈRE LA PORTE'}</span><h2>${old?boss.name:'Un gardien à découvrir'}</h2><p>Niveau ${Math.min(100,7+floor*2)} · Un boss géant · Six Pokémon par dresseur</p><div class="den-rewards"><b>${old?'✓ Récompenses déjà récupérées':'Récompenses de première victoire'}</b><span>▱ 2 tickets · ◈ 2 bonbons · ✦ 50 poussières</span><small>${old?'Rejouer n’accorde aucune récompense ni expérience supplémentaire.':'+ '+(30+floor*10)+' XP par Pokémon de ton équipe.'}</small></div><div class="den-entry-actions"><button class="primary" data-act="den-fight" data-floor="${floor}">${old?'Réaffronter '+boss.name:'Entrer dans la grotte'} →</button><button data-act="route" data-page="friends">Préparer un raid entre amis</button><button data-act="route" data-page="team">Mon équipe</button></div></div></section><aside class="den-journal"><div class="section-title"><h2>Les gardiens de l’Antre</h2><span>${frontier-1} vaincu${frontier>2?'s':''}</span></div><button class="den-journal-boss ${floor===frontier?'selected':''}" data-act="den-select" data-floor="${frontier}"><span class="den-journal-icon">◇</span><span><small>PROCHAIN GARDIEN · ANTRE ${frontier}</small><b>${denBoss(g.dex,frontier).types.map(t=>TYPE_NAMES[t]).join(' · ')}</b></span><i>→</i></button><h3>Rencontres précédentes</h3>${frontier===1?'<p class="den-empty-history">Ta première victoire ouvrira ton carnet de rencontres. Tu pourras revenir affronter chaque ancien gardien.</p>':''}<div class="den-history">${Array.from({length:frontier-start},(_,i)=>frontier-1-i).map(n=>{const p=denBoss(g.dex,n);return `<button class="den-journal-boss ${floor===n?'selected':''}" data-act="den-select" data-floor="${n}"><img src="${icon(String(p.id))}" alt=""><span><small>ANTRE ${n} · ✓ VAINCU</small><b>${p.name}</b><small>Récompenses récupérées</small></span><i>↻</i></button>`}).join('')}</div>${start>1?'<button data-act="den-older" class="den-older">Voir les rencontres plus anciennes</button>':''}</aside></div>`;
}
